?>
                    <div class="page-intro"><div><h2>Ring up a customer</h2><p>Add products to the cart, then record the payment.</p></div><span class="count-badge"><?php echo count($cartItems); ?> cart items</span></div>
                    <div class="pos-layout"><section class="panel"><div class="panel-heading"><div><h3>Available products</h3><p>Choose an item to add it to the cart.</p></div></div><div class="pos-product-list">
