                            <div class="cart-lines"><?php foreach ($cartItems as $line): ?><div class="cart-line"><div class="cart-line-title"><strong><?php echo e($line['product']['name']); ?></strong><form method="post"><input type="hidden" name="csrf" value="<?php echo e($_SESSION['csrf']); ?>"><input type="hidden" name="action" value="remove_from_cart"><input type="hidden" name="product_id" value="<?php echo e($line['product']['id']); ?>"><button class="remove-item" type="submit" aria-label="Remove item"><?php echo icon('close'); ?></button></form></div><div class="cart-line-bottom"><form method="post" class="quantity-form"><input type="hidden" name="csrf" value="<?php echo e($_SESSION['csrf']); ?>"><input type="hidden" name="action" value="update_cart"><input type="hidden" name="product_id" value="<?php echo e($line['product']['id']); ?>"><input name="quantity" type="number" min="1" max="<?php echo (int) $line['product']['stock']; ?>" value="<?php echo $line['quantity']; ?>" aria-label="Cart quantity"><button type="submit">Update</button></form><strong><?php echo money($line['subtotal']); ?></strong></div></div><?php endforeach; ?></div>
                            <div class="cart-total"><span>Total due</span><strong><?php echo money($cartTotal); ?></strong></div>
                            <form method="post" class="payment-form"><input type="hidden" name="csrf" value="<?php echo e($_SESSION['csrf']); ?>"><input type="hidden" name="action" value="checkout"><label>Payment method<select name="payment_method"><option>Cash</option><option>GCash</option><option>Card</option></select></label><label>Amount received (₱)<input name="amount_paid" type="number" min="<?php echo e(number_format($cartTotal, 2, '.', '')); ?>" step="0.01" required placeholder="<?php echo e(number_format($cartTotal, 2, '.', '')); ?>"></label><button class="button button-primary button-wide" type="submit">Complete sale <span>→</span></button></form>
                        <?php endif; ?>
                    </section></div>
